<?php
$pageTitle='Request a Booking';$theme='burgundy';require_once 'includes/user-auth.php';$vendorId=(int)($_GET['vendor_id']??$_POST['vendor_id']??0);$serviceId=(int)($_GET['service_id']??$_POST['service_id']??0);$v=$vendorId?$pdo->query('SELECT * FROM vendors WHERE id='.$vendorId)->fetch():null;$s=$serviceId?$pdo->query('SELECT * FROM services WHERE id='.$serviceId)->fetch():null;$areas=$pdo->query('SELECT * FROM areas WHERE active=1 ORDER BY name')->fetchAll();$success='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$phone=trim($_POST['phone']);$email=trim($_POST['email']);$type=trim($_POST['event_type']);$date=$_POST['event_date'];$area=(int)$_POST['area_id'];$location=trim($_POST['location']);$guests=(int)$_POST['guests'];$budget=(float)$_POST['budget'];$req=trim($_POST['requirements']);if($name===''||$phone===''||$type===''||$date===''||$location==='')$errors[]='Please complete all required fields.';if(!$errors){$no='BKG-'.date('Ymd').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO bookings(booking_no,service_id,vendor_id,user_id,name,phone,email,event_type,event_date,area_id,location,guests,budget,requirements) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$no,$serviceId?:null,$vendorId?:null,$_SESSION['user_id']??null,$name,$phone,$email,$type,$date,$area?:null,$location,$guests,$budget,$req]);$pdo->prepare('INSERT INTO notifications(title,message,type) VALUES(?,?,?)')->execute(['New booking request',$no.' from '.$name,'booking']);$success='Booking request '.$no.' received. Save this number to track your booking.';}}
include 'includes/header.php';?><section class="py-5"><div class="container"><div class="row justify-content-center"><div class="col-lg-9"><div class="content-card p-4 p-md-5"><h2>Request a booking</h2><p class="text-muted">Tell us your event details. The admin team will confirm availability.</p><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?><div class="mt-2"><a href="track-booking.php" class="btn btn-sm btn-dark">Track Booking</a></div></div><?php endif;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?=htmlspecialchars($e)?></div><?php endforeach;?><form method="post" class="row g-3 needs-validation" novalidate><input type="hidden" name="vendor_id" value="<?=$vendorId?>"><input type="hidden" name="service_id" value="<?=$serviceId?>"><div class="col-md-6"><label class="form-label">Name *</label><input name="name" class="form-control" required></div><div class="col-md-6"><label class="form-label">Phone *</label><input name="phone" class="form-control" required></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" type="email" class="form-control"></div><div class="col-md-6"><label class="form-label">Event Type *</label><select name="event_type" class="form-select" required><option>Wedding</option><option>Birthday</option><option>Engagement</option><option>Baby Shower</option><option>Corporate Event</option><option>Anniversary</option><option>Proposal</option></select></div><div class="col-md-6"><label class="form-label">Event Date *</label><input type="date" name="event_date" class="form-control" required></div><div class="col-md-6"><label class="form-label">Area</label><select name="area_id" class="form-select"><option value="0">Choose</option><?php foreach($areas as $a):?><option value="<?=$a['id']?>"><?=htmlspecialchars($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Event Location *</label><input name="location" class="form-control" required></div><div class="col-md-3"><label class="form-label">Guests</label><input type="number" name="guests" class="form-control"></div><div class="col-md-3"><label class="form-label">Budget</label><input type="number" name="budget" class="form-control"></div><div class="col-12"><label class="form-label">Requirements</label><textarea name="requirements" rows="4" class="form-control"></textarea></div><div class="col-12"><button class="btn btn-brand w-100" style="background:var(--burgundy)">Submit Booking Request</button></div></form></div></div></div></div></section><?php include 'includes/footer.php'; ?>
